DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'campagne_contacts_pkey' AND conrelid = 'campagne_contacts'::regclass) THEN
        ALTER TABLE campagne_contacts ADD CONSTRAINT campagne_contacts_pkey PRIMARY KEY (campagne_id, contact_id);
    END IF;
END
$$;

